 * @return global error handler
 */
private ErrorHandler defineGlobalErrorHandler(Jooby app) {
    // PATH: Test should invoke the next Jooby.problemDetailsIsEnabled(...) [step in execution path]
    if (app.problemDetailsIsEnabled()) {
