/**
 * Setup default environment, logging (logback or log4j2) and run application.
 *
 * @param args
 * 		Application arguments.
 * @param server
 * 		Server.
 * @param executionMode
 * 		Default application execution mode. Can be overridden by application.
 * @param provider
 * 		Application provider.
 */
public static void runApp(@NonNull
String[] args, @NonNull
Server server, @NonNull
ExecutionMode executionMode, @NonNull
List<Supplier<Jooby>> provider) {
    /* Dump command line as system properties. */
    parseArguments(args).forEach(System::setProperty);
    ServerOptions appServerOptions = null;
    var apps = new ArrayList<Jooby>();
    var targetServer = (server.getLoggerOff().isEmpty()) ? server : MutedServer.mute(server);
    try {
        for (var factory : provider) {
            var app = createApp(server, executionMode, factory);
            /* When running a single app instance, there is no issue with server options.
            When multiple apps pick first in the provided order.
             */
            if (appServerOptions == null) {
                appServerOptions = // PATH: Test should invoke the next ServerOptions.from(...) [step in execution path]
                ServerOptions.from(app.getConfig()).orElse(null);
            }
            apps.add(app);
        }
        // Override when there is something and server options were not set
        if (server.getOptions().defaults && (appServerOptions != null)) {
            server.setOptions(appServerOptions);
        }
        targetServer.start(apps.toArray(new Jooby[0]));
    } catch (Throwable startupError) {
        try {
            targetServer.stop();
        } catch (Throwable ignored) {
            // no need to log here
        }
        // rethrow
        throw startupError instanceof StartupException ? ((StartupException) (startupError)) : new StartupException("Application initialization resulted in exception", startupError);
    }
}

/**
 * Creates server options from config object. The configuration options must provided entries
 * like: <code>server.port</code>, <code>server.ioThreads</code>, etc...
 *
 * @param conf
 * 		Configuration object.
 * @return Server options.
 */
public static Optional<ServerOptions> from(@NonNull
Config conf) {
    if (conf.hasPath("server")) {
        var options = new ServerOptions();
        if (conf.hasPath("server.port")) {
            options.setPort(conf.getInt("server.port"));
        }
        if (conf.hasPath("server.securePort")) {
            options.setSecurePort(conf.getInt("server.securePort"));
        }
        if (conf.hasPath("server.ioThreads")) {
            options.setIoThreads(conf.getInt("server.ioThreads"));
        }
        if (conf.hasPath("server.name")) {
            options.setServer(conf.getString("server.name"));
        }
        if (conf.hasPath("server.output.size")) {
            options.output.setSize(conf.getInt("server.output.size"));
        }
        if (conf.hasPath("server.output.useDirectBuffers")) {
            options.output.setDirectBuffers(conf.getBoolean("server.output.useDirectBuffers"));
        }
        if (conf.hasPath("server.defaultHeaders")) {
            options.setDefaultHeaders(conf.getBoolean("server.defaultHeaders"));
        }
        if (conf.hasPath("server.gzip")) {
            throw new UnsupportedOperationException("server.gzip was removed, use server.compressionLevel instead.");
        }
        if (conf.hasPath("server.compressionLevel")) {
            options.setCompressionLevel(conf.getInt("server.compressionLevel"));
        }
        if (conf.hasPath("server.maxRequestSize")) {
            options.setMaxRequestSize(// PATH: Test should invoke the next Config.getMemorySize(...) [step in execution path]
            ((int) (conf.getMemorySize("server.maxRequestSize").toBytes())));
        }
        if (conf.hasPath("server.maxFormFields")) {
            options.setMaxFormFields(conf.getInt("server.maxFormFields"));
        }
        if (conf.hasPath("server.workerThreads")) {
            options.setWorkerThreads(conf.getInt("server.workerThreads"));
        }
        if (conf.hasPath("server.host")) {
            options.setHost(conf.getString("server.host"));
        }
        if (conf.hasPath("server.expectContinue")) {
            options.setExpectContinue(conf.getBoolean("server.expectContinue"));
        }
        // ssl
        SslOptions.from(conf, "server.ssl").ifPresent(options::setSsl);
        if (conf.hasPath("server.httpsOnly")) {
            options.httpsOnly = conf.getBoolean("server.httpsOnly");
        }
        if (conf.hasPath("server.http2")) {
            options.setHttp2(conf.getBoolean("server.http2"));
        }
        return Optional.of(options);
    }
    return Optional.empty();
}

