/**
 * Call back method that indicates application was deployed.
 *
 * @param server
 * 		Server.
 * @return This application.
 */
public Jooby start(@NonNull
Server server) // PATH: Test should invoke the next RouterImpl.start(...) [step in execution path]
{
    Path tmpdir = getTmpdir();
    ensureTmpdir(tmpdir);
    log.trace("initialization context static variables {} {}", Context.RFC1123, Context.GMT);
    if (locales == null) {
        String path = AvailableSettings.LANG;
        locales = Optional.of(getConfig()).filter(c -> c.hasPath(path)).map(c -> c.getString(path)).map(v -> LocaleUtils.parseLocales(v).orElseThrow(() -> new RuntimeException(String.format("Invalid value for configuration property '%s'; check the" + " documentation of %s#parse(): %s", path, Locale.LanguageRange.class.getName(), v)))).orElseGet(() -> singletonList(Locale.getDefault()));
    }
    var services = getServices();
    services.put(Environment.class, getEnvironment());
    services.put(Config.class, getConfig());
    joobyRunHook(getClass().getClassLoader(), server);
    router.initialize();
    for (Extension extension : lateExtensions) {
        try {
            extension.install(this);
        } catch (Throwable e) {
            throw SneakyThrows.propagate(e);
        }
    }
    this.lateExtensions.clear();
    this.lateExtensions = null;
    this.startingCallbacks = fire(this.startingCallbacks);
    router.start(this, server);
    return this;
}

@NonNull
public Router start(@NonNull
Jooby app, @NonNull
Server server) {
    started = true;
    // PATH: Test should invoke the next RouterImpl.defineGlobalErrorHandler(...) [step in execution path]
    var globalErrHandler = defineGlobalErrorHandler(app);
    if (err == null) {
        err = globalErrHandler;
    } else {
        err = err.then(globalErrHandler);
    }
    ExecutionMode mode = app.getExecutionMode();
    for (Route route : routes) {
        String executorKey = route.getExecutorKey();
        Executor executor;
        if (executorKey == null) {
            executor = routeExecutor.get(route);
            if (executor instanceof ForwardingExecutor) {
                executor = ((ForwardingExecutor) (executor)).executor;
            }
        } else if (executorKey.equals("worker")) {
            executor = (worker instanceof ForwardingExecutor) ? ((ForwardingExecutor) (worker)).executor : worker;
        } else {
            executor = executor(executorKey);
        }
        /**
         * Default web socket values:
         */
        if (route.getHandler() instanceof WebSocketHandler) {
            if (route.getConsumes().isEmpty()) {
                // default type
                route.setConsumes(Collections.singletonList(MediaType.json));
            }
            if (route.getProduces().isEmpty()) {
                // default type
                route.setProduces(Collections.singletonList(MediaType.json));
            }
        } else {
            /**
             * Consumes && Produces (only for HTTP routes (not web socket)
             */
            route.setFilter(prependMediaType(route.getConsumes(), route.getFilter(), Route.SUPPORT_MEDIA_TYPE));
            route.setFilter(prependMediaType(route.getProduces(), route.getFilter(), Route.ACCEPT));
        }
        Route.Handler pipeline = Pipeline.build(route, forceMode(route, mode), executor, postDispatchInitializer);
        route.setPipeline(pipeline);
        /**
         * Final render
         */
        route.setEncoder(encoder);
    }
    ((Chi) (chi)).setEncoder(encoder);
    /**
     * router options:
     */
    if (routerOptions.isIgnoreCase()) {
        chi = new RouteTreeLowerCasePath(chi);
    }
    if (routerOptions.isIgnoreTrailingSlash()) {
        chi = new RouteTreeIgnoreTrailingSlash(chi);
    }
    if (routerOptions.isNormalizeSlash()) {
        chi = new RouteTreeNormPath(chi);
    }
    // unwrap executor
    worker = ((ForwardingExecutor) (worker)).executor;
    this.stack.forEach(Stack::clear);
    this.stack = null;
    routeExecutor.clear();
    routeExecutor = null;
    return this;
}

/**
 * Define the global error handler. If ProblemDetails is enabled the {@link ProblemDetailsHandler}
 * instantiated from configuration settings and returned. Otherwise, {@link DefaultErrorHandler}
 * instance returned.
 *
 * @param app
 * 		- Jooby application instance
 * @return global error handler
 */
private ErrorHandler defineGlobalErrorHandler(Jooby app) {
    if (app.problemDetailsIsEnabled()) {
        // PATH: Test should invoke the next ProblemDetailsHandler.from(...) [step in execution path]
        return ProblemDetailsHandler.from(app.getConfig());
    } else {
        return ErrorHandler.create();
    }
}

/**
 * Creates a problem handler from configuration.
 *
 * <pre>{@code problem.details {
 *   enable: true
 *   muteCodes: [401, 106]
 *   muteTypes: ['com.example.MyException']
 * }}</pre>
 *
 * @param conf
 * 		Configuration.
 * @return Problem handler.
 */
public static ProblemDetailsHandler from(Config conf) {
    var handler = new ProblemDetailsHandler();
    if (conf.hasPath(ROOT_CONFIG_PATH)) {
        var problemConfig = conf.getConfig(ROOT_CONFIG_PATH);
        if (problemConfig.hasPath(LOG_4XX_ERRORS_KEY) && problemConfig.getBoolean(LOG_4XX_ERRORS_KEY)) {
            handler.log4xxErrors();
        }
        if (problemConfig.hasPath(MUTE_CODES_KEY)) {
            problemConfig.getIntList(MUTE_CODES_KEY).forEach(code -> handler.mute(StatusCode.valueOf(code)));
        }
        if (problemConfig.hasPath(MUTE_TYPES_KEY)) {
            var classLoader = ProblemDetailsHandler.class.getClassLoader();
            problemConfig.getStringList(MUTE_TYPES_KEY).forEach(throwingConsumer(className -> handler.mute(((Class<? extends Exception>) (classLoader.loadClass(className))))));
        }
    }
    return handler;
}

